// WAHA inbound -> lead. So mensagem que CHEGA e que cita uma peca.
//
// REGRA DURA - o Config esta com includeOtherFields=true, entao o body do
// webhook chega aqui dentro do $input junto com os tokens. Nao chamar
// $('Webhook...') pelo nome: ao importar por cima de um canvas existente o n8n
// renomeia os nos (Config -> Config1) e a referencia morre em silencio.
//
// NAO usar barra invertida em regex: some ao colar o codigo na mao no n8n.
const inp = $input.first().json;
const body = inp.body || {};
const p = body.payload || {};

// 1) Nunca reagir ao proprio envio.
if (p.fromMe) return [];

const from = String(p.from || '');
if (!from) return [];

// 2) Ignorar GRUPO. O hook dispara pra tudo - inclusive a oferta que o bot
//    acabou de postar. Sem este freio, cada disparo viraria um lead fantasma.
if (from.indexOf('@g.us') > -1) return [];

// 3) Precisa citar uma peca. O CTA manda "Estou interessado! (m71370664392)".
const texto = String(p.body || '');
const m = texto.match(/m[0-9]+/i);
if (!m) return [];   // "oi" solto nao vira lead; o Bruno le no WhatsApp normal

const d = p._data || {};
// wa_id = o id cru do WhatsApp. Pode ser LID (@lid) ou telefone (@c.us).
// Quem traduz e o node 'WAHA: resolver o numero'. NAO usar isto como telefone.
return [{ json: {
  mercari_id: m[0].toLowerCase(),
  wa_id: from,
  phone_bruto: from.split('@')[0],
  nome_wa: String(p.notifyName || d.notifyName || p.pushName || '').trim(),
  mensagem: texto,
  recebido_em: new Date().toISOString()
}}];

// Junta as duas consultas e monta a linha do lead.
//  - $input          = os leads QUE JA EXISTEM desta peca (dedup + ordinal)
//  - achar a peca    = a linha da 556 (row_id pro link + title_pt pro aviso)
const lead = $('Filtrar + montar lead').first().json;

// TELEFONE DE VERDADE. O `from` do WhatsApp vem como LID (identidade interna),
// nao como numero: gravar ele em `phone` gerava "wa.me/21522181840928", link morto.
// O campo certo do contato e `id` (o `number` e o LID de novo).
// LID desconhecido volta com id terminando em @lid -> nao resolveu -> phone fica
// vazio e o aviso omite o wa.me, em vez de mandar um link quebrado.
const contato = $('WAHA: resolver o numero').first().json || {};
const contatoId = String(contato.id || '');
const phone = contatoId.indexOf('@c.us') > -1 ? contatoId.split('@')[0] : '';
lead.phone = phone;
lead.nome_wa = lead.nome_wa || String(contato.pushname || '').trim();

// Sem telefone resolvido o dedup nao tem chave estavel -> cai pro wa_id, que e
// estavel por pessoa do mesmo jeito. So nao serve de link.
const chave = phone || String(lead.wa_id || '');
const pecaRows = ($input.first().json.results) || [];   // agora o input e a peca

// O DEDUP NAO MORA MAIS AQUI. Ele vivia neste ponto (GET antes do INSERT) e
// perdia pra corrida: o WAHA entrega o mesmo evento 2x com ~40ms de diferenca,
// e as duas execucoes consultavam antes de qualquer uma gravar.
// Agora grava-se sempre e reconcilia-se depois, em 'Reconciliar + ordinal'.
const peca = pecaRows.length ? pecaRows[0] : null;
const titulo = (peca && peca.title_pt) ? peca.title_pt : lead.mercari_id;

// A linha vai montada daqui: o HTTP node so faz JSON.stringify($json.row).
// Campo `peca` = link_row -> quer um ARRAY de row_id, nao o mercari_id.
// Peca nao encontrada (link solto): grava o lead assim mesmo, com peca vazia.
// Perder o lead por causa do link seria pior que um link faltando.
const row = {
  lead: lead.nome_wa || phone || lead.wa_id,
  phone: lead.phone,
  wa_id: lead.wa_id,
  nome_wa: lead.nome_wa,
  mercari_id: lead.mercari_id,
  peca: peca ? [peca.id] : [],
  mensagem: lead.mensagem,
  recebido_em: lead.recebido_em,
  status: 'Novo',
  avisado_vendido: false
};

// ordinal nao sai daqui: so da pra saber a posicao depois de gravar.
return [{ json: { row: row, peca_titulo: titulo } }];

// Monta o aviso pro Bruno. O lead JA foi gravado - se este no falhar, o dado
// esta salvo e so o ping se perde.
const cfg = $('Config').first().json;
const d = $('Reconciliar + ordinal').first().json;

const quem = d.nome_wa || d.phone || d.wa_id;
const nth = d.ordinal > 1 ? ' (' + d.ordinal + 'a pessoa)' : '';

// So monta o wa.me se o numero foi resolvido de verdade (ver 'WAHA: resolver o
// numero'). Link com LID dentro nao abre no WhatsApp - melhor nao mandar link
// nenhum e dizer o porque do que mandar um que o Bruno clica e toma erro.
const linha3 = d.phone
  ? 'wa.me/' + d.phone
  : 'numero nao resolvido - procura por "' + quem + '" no WhatsApp da loja';

const texto = '\u{1F514} Lead: ' + quem + '\n' + d.peca_titulo + nth + '\n' + linha3;

// Sem admin_id nao ha pra quem avisar. O lead continua gravado.
const destino = String(cfg.admin_id || '').trim();
if (!destino) return [];

return [{ json: { payload: {
  session: cfg.waha_session,
  chatId: destino,
  text: texto
}}}];

// RECONCILIACAO. Ja gravei minha linha; agora descubro se ela e a que vale.
//
// Nao ha lock e nao precisa: as duas execucoes chegam na MESMA conclusao
// sozinhas, porque o Baserow da row_id crescente e "o menor id vence" e uma
// regra que as duas conseguem avaliar sem falar uma com a outra.
// (O certo seria o banco arbitrar com unique constraint, mas este Baserow nao
// tem: a API de campos nao expoe field_constraints.)
const minha = $('Baserow: gravar lead').first().json;
const todas = ($input.first().json.results) || [];

// A chave da pessoa: telefone quando o WAHA resolveu o LID, senao o proprio
// wa_id (que e estavel por pessoa do mesmo jeito - so nao serve de link).
function chaveDe(r) {
  return String((r && r.phone) || '').trim() || String((r && r.wa_id) || '').trim();
}
const eu = chaveDe(minha);

// irmas = linhas da MESMA pessoa nesta peca, inclusive a minha.
const irmas = todas.filter(function (r) { return chaveDe(r) && chaveDe(r) === eu; });
const meNaLista = irmas.some(function (r) { return r.id === minha.id; });

// FAIL-SAFE: se eu nao me acho na lista, algo saiu do script (filtro, paginacao,
// replicacao atrasada). Nesse caso MANTENHO a linha e aviso.
// Aqui o pior caso e o Bruno ver 2 pings; perder um lead e perder venda.
// (No disparo o fail-safe e o oposto - la quem leva a duplicata e o cliente.)
let souEu = true;
if (meNaLista) {
  const menor = irmas.reduce(function (a, b) { return a.id < b.id ? a : b; });
  souEu = menor.id === minha.id;
}

// ORDINAL = quantas PESSOAS distintas chegaram nesta peca ate mim.
// Contar LINHAS era o que dava "3a pessoa" havendo 2 pessoas: a duplicata contava.
const pessoas = [];
todas.forEach(function (r) {
  if (r.id > minha.id) return;                 // quem chegou depois nao conta
  const k = chaveDe(r);
  if (k && pessoas.indexOf(k) === -1) pessoas.push(k);
});

return [{ json: {
  sou_eu: souEu,
  meu_id: minha.id,
  ordinal: Math.max(1, pessoas.length),
  peca_titulo: $('Montar a linha').first().json.peca_titulo,
  phone: minha.phone || '',
  wa_id: minha.wa_id || '',
  nome_wa: minha.nome_wa || ''
}}];
